1	// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
2	// Authoring builds as CODE: design one bay, tile it; mirror for symmetry; protect function with a guard.
3	// Coordinate bookkeeping is where design time and errors go — write a short generator script with these helpers
4	// instead of typing hundreds of coordinates.
5	//
6	//   import { load, Grid, guard, tile, mirrorX, B, face } from "<plugin>/tools/src/build.mjs"
7	//   const g = guard(load("in.nbt"))                 // refuses writes into functional cells (see check.mjs)
8	//   runParts(g, [["shell", shellPart], ["porch", porchPart]], { palette: "palette.json" })  // later parts only add
9	//   tile(g, { from: 1, step: 4, count: 5, axis: "z" }, (z) => bay(g, z))
10	//   g.save("out.nbt")
11	import { existsSync, readFileSync, writeFileSync } from "node:fs";
12	import { load, Grid, ns } from "./structure.mjs";
13	import { t } from "./nbt.mjs";
14	import { functionalCells } from "./check.mjs";
15	import { reroof } from "./roofs.mjs";
16	export { load, Grid };
17	
18	// ---- directions -------------------------------------------------------------------------------------------------
19	export const DIRS = { north: [0, 0, -1], south: [0, 0, 1], west: [-1, 0, 0], east: [1, 0, 0] };
20	export const OPPOSITE = { north: "south", south: "north", east: "west", west: "east", up: "down", down: "up" };
21	const CW = { north: "east", east: "south", south: "west", west: "north" };
22	export const face = {
23	  opposite: (f) => OPPOSITE[f],
24	  cw: (f) => CW[f],
25	  ccw: (f) => OPPOSITE[CW[f]],
26	  /** Mirror a facing across the YZ plane (x -> -x) or XY plane (z -> -z). */
27	  mirrorX: (f) => (f === "east" ? "west" : f === "west" ? "east" : f),
28	  mirrorZ: (f) => (f === "north" ? "south" : f === "south" ? "north" : f),
29	};
30	
31	// ---- block helpers: return [block, state] pairs for g.set(x, y, z, ...B.stairs(...)) ----------------------------
32	// Stairs `facing` = the side of the full-height back; a cornice/bracket lip toward the street uses
33	// facing = the INWARD direction with half: "top".
34	export const B = {
35	  stairs: (mat, facing, half = "bottom", shape = "straight") => [`${mat}_stairs`, { facing, half, shape, waterlogged: "false" }],
36	  slab: (mat, type = "bottom") => [`${mat}_slab`, { type, waterlogged: "false" }],
37	  log: (mat, axis = "y") => [`${mat}_log`, { axis }],
38	  wood: (mat, axis = "y") => [`${mat}_wood`, { axis }],
39	  pillar: (block, axis = "y") => [block, { axis }],
40	  trapdoor: (mat, facing, half = "bottom", open = false) => [`${mat}_trapdoor`, { facing, half, open: String(open), powered: "false", waterlogged: "false" }],
41	  door: (mat, facing, half = "lower", hinge = "left") => [`${mat}_door`, { facing, half, hinge, open: "false", powered: "false" }],
42	  fence: (mat) => [`${mat}_fence`, {}],
43	  wall: (mat) => [`${mat}_wall`, {}],
44	  pane: (block = "glass_pane") => [block, {}],
45	  lantern: (hanging = false) => ["lantern", { hanging: String(hanging), waterlogged: "false" }],
46	  chain: (axis = "y", version26 = true) => [version26 ? "iron_chain" : "chain", { axis, waterlogged: "false" }],
47	  wallTorch: (facing) => ["wall_torch", { facing }],
48	  block: (name) => [name, {}],
49	  /**
50	   * A banner with patterns: [block, state, nbt] for g.set(x, y, z, ...B.banner(...)). patterns: [[pattern, colour], ...]
51	   * (ids such as stripe_center, border, cross, rhombus, flower, globe, gradient, half_horizontal, curly_border).
52	   * wall: hung on the block behind it, facing `facing`; standing: `rotation` 0..15 (0 faces south). legacy: the
53	   * pre-1.20.5 Patterns/Pattern/Color form (for 1.20.4 and older).
54	   */
55	  banner: (color, patterns = [], { wall = true, facing = "north", rotation = 0, legacy = false } = {}) => {
56	    const block = wall ? `${color}_wall_banner` : `${color}_banner`, state = wall ? { facing } : { rotation: String(rotation) };
57	    const pats = patterns.map((p) => (Array.isArray(p) ? { pattern: p[0], color: p[1] } : p));
58	    const nbt = legacy
59	      ? t.compound({ id: t.string("minecraft:banner"), Patterns: t.list("compound", pats.map((p) => ({ Pattern: t.string(LEGACY_PATTERN[p.pattern] ?? p.pattern), Color: t.int(DYE_INDEX.indexOf(p.color)) }))) })
60	      : t.compound({ id: t.string("minecraft:banner"), patterns: t.list("compound", pats.map((p) => ({ pattern: t.string(`minecraft:${p.pattern.replace(/^minecraft:/, "")}`), color: t.string(p.color) }))) });
61	    return [block, state, nbt];
62	  },
63	  /**
64	   * A sign with text: [block, state, nbt]. lines: up to 4 strings (front); back: up to 4 more. wood "oak", "spruce" ...
65	   * wall (facing) or standing (rotation 0..15); hanging: a hanging sign. color: dye name; glow: glowing text.
66	   * dataVersion: text is written as JSON components before 1.21.5 (4325) and as plain string components after.
67	   */
68	  sign: (wood = "oak", lines = [], { wall = true, facing = "north", rotation = 0, hanging = false, color = "black", glow = false, back = [], dataVersion = 4189 } = {}) => {
69	    const block = `${wood}_${wall ? "wall_" : ""}${hanging ? "hanging_" : ""}sign`;
70	    const state = wall ? { facing, waterlogged: "false" } : { rotation: String(rotation), waterlogged: "false", ...(hanging ? { attached: "false" } : {}) };
71	    const msg = (s) => t.string(dataVersion >= 4325 ? String(s ?? "") : JSON.stringify({ text: String(s ?? "") }));
72	    const side = (ls) => ({ messages: t.list("string", [0, 1, 2, 3].map((i) => msg(ls[i]).value)), color: t.string(color), has_glowing_text: t.byte(glow ? 1 : 0) });
73	    const nbt = t.compound({ id: t.string(hanging ? "minecraft:hanging_sign" : "minecraft:sign"), is_waxed: t.byte(0), front_text: t.compound(side(lines)), back_text: t.compound(side(back)) });
74	    return [block, state, nbt];
75	  },
76	};
77	const DYE_INDEX = ["white", "orange", "magenta", "light_blue", "yellow", "lime", "pink", "gray", "light_gray", "cyan", "purple", "blue", "brown", "green", "red", "black"];
78	const LEGACY_PATTERN = { base: "b", stripe_bottom: "bs", stripe_top: "ts", stripe_left: "ls", stripe_right: "rs", stripe_center: "cs", stripe_middle: "ms",
79	  stripe_downright: "drs", stripe_downleft: "dls", small_stripes: "ss", cross: "cr", straight_cross: "sc", diagonal_left: "ld", diagonal_right: "rud",
80	  half_vertical: "vh", half_horizontal: "hh", half_horizontal_bottom: "hhb", triangle_bottom: "bt", triangle_top: "tt", circle: "mc", rhombus: "mr",
81	  border: "bo", curly_border: "cbo", bricks: "bri", gradient: "gra", gradient_up: "gru", creeper: "cre", skull: "sku", flower: "flo", mojang: "moj", globe: "glb" };
82	
83	// ---- placement helpers ------------------------------------------------------------------------------------------
84	/** Call fn(pos, i) for count positions from `from`, `step` apart (the bay rhythm). */
85	export function tile(_g, { from = 0, step, count, to }, fn) {
86	  const n = count ?? Math.floor((to - from) / step) + 1;
87	  for (let i = 0; i < n; i++) fn(from + i * step, i);
88	}
89	
90	/** Run `paint(set)` twice: as written, and mirrored across x = cx (x' = 2cx - x), flipping east/west facings. */
91	export function mirrorX(g, cx, paint) {
92	  paint((x, y, z, block, state) => g.set(x, y, z, block, state));
93	  paint((x, y, z, block, state) => g.set(2 * cx - x, y, z, block, state && state.facing ? { ...state, facing: face.mirrorX(state.facing) } : state));
94	}
95	export function mirrorZ(g, cz, paint) {
96	  paint((x, y, z, block, state) => g.set(x, y, z, block, state));
97	  paint((x, y, z, block, state) => g.set(x, y, 2 * cz - z, block, state && state.facing ? { ...state, facing: face.mirrorZ(state.facing) } : state));
98	}
99	
100	/** Hollow box: walls (and optional floor/ceiling) of a cuboid. */
101	export function shell(g, a, b, block, { floor = true, ceiling = true, state } = {}) {
102	  const [x0, y0, z0] = a.map((v, i) => Math.min(v, b[i])), [x1, y1, z1] = a.map((v, i) => Math.max(v, b[i]));
103	  for (let x = x0; x <= x1; x++) for (let y = y0; y <= y1; y++) for (let z = z0; z <= z1; z++) {
104	    const edge = x === x0 || x === x1 || z === z0 || z === z1 || (floor && y === y0) || (ceiling && y === y1);
105	    if (edge) g.set(x, y, z, block, state);
106	  }
107	}
108	
109	/** Set a box to air (carving). Air is stored, so it clears the cell when the structure is placed. */
110	export const carve = (g, a, b) => g.fill(a, b, "minecraft:air");
111	
112	/** Replace only where the current block matches `from` (a name or a predicate). */
113	export function replace(g, a, b, from, block, state) {
114	  const match = typeof from === "function" ? from : (n) => n === ns(from);
115	  for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
116	    for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
117	      for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) if (match(g.blockAt(x, y, z))) g.set(x, y, z, block, state);
118	}
119	
120	/**
121	 * Wrap a grid so writes into protected cells are refused (counted, never thrown), so a decor script cannot
122	 * break function. protect: Set of "x,y,z" — default: the grid's own functional cells and the cells that must stay
123	 * clear around them (check.mjs functionalCells). `g.refused` lists what was blocked; report it.
124	 */
125	export function guard(g, protect) {
126	  const cells = protect ?? (() => { const f = functionalCells(g); return new Set([...f.protect.keys(), ...f.keepClear]); })();
127	  const refused = [];
128	  return new Proxy(g, {
129	    get(target, prop) {
130	      if (prop === "refused") return refused;
131	      if (prop === "protected") return cells;
132	      if (prop === "set") return (x, y, z, ...rest) => { if (cells.has(`${x},${y},${z}`)) { refused.push([x, y, z, rest[0]]); return target; } return target.set(x, y, z, ...rest); };
133	      if (prop === "fill") return (a, b, block, state) => { for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++) for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++) for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) { if (cells.has(`${x},${y},${z}`)) refused.push([x, y, z, block]); else target.set(x, y, z, block, state); } return target; };
134	      const v = Reflect.get(target, prop);
135	      return typeof v === "function" ? v.bind(target) : v;
136	    },
137	  });
138	}
139	
140	/**
141	 * Draw blocks from text, the way Litematica stores a schematic (a palette, then one index per cell): one character per
142	 * block, a legend for the characters. Far fewer tokens than a set() per block, and the layout is visible as written.
143	 *   layers(g, [x, y, z], { "#": "oak_planks", "b": ["red_bed", { facing: "south", part: "head" }], "c": "chest" }, [
144	 *     ["#####", "#b c#", "#b  #"],      // y: rows run along +x, successive rows along +z
145	 *     ["#####", "#   #", "#   #"],      // y + 1 ...
146	 *   ])
147	 * A single layer may be passed as one array of rows. Characters not in the legend (space, ".") are left as they are.
148	 * Writes go through g.set, so runParts' lock and palette report apply. Returns the number of blocks placed.
149	 */
150	export function layers(g, [x0, y0, z0], legend, rowsOrLayers) {
151	  const list = typeof rowsOrLayers[0] === "string" ? [rowsOrLayers] : rowsOrLayers;
152	  let n = 0;
153	  list.forEach((rows, dy) => rows.forEach((row, dz) => [...row].forEach((ch, dx) => {
154	    const e = legend[ch];
155	    if (e == null) return;
156	    const [block, state, nbt] = Array.isArray(e) ? e : [e];
157	    g.set(x0 + dx, y0 + dy, z0 + dz, block, state, nbt);
158	    n++;
159	  })));
160	  return n;
161	}
162	
163	/**
164	 * Run a build's parts in order so each part can only ADD to what earlier parts built: a write into a cell an earlier
165	 * part placed (air included, so no carving) is refused, counted, never thrown, so a later part can't knock holes in
166	 * a wall. Cells set before runParts (the ground) stay writable: farmland and paths may replace grass. With a palette
167	 * (palette.json, or its object: { roles: { role: [blocks] }, objects: [blocks] }), every block placed outside it is
168	 * reported. Prints one line per part, writes the reports to `report` (default parts-report.json; null for none) and
169	 * returns them.
170	 * roof: a roof spec (roof.json, as for `mcd roof --spec`) laid right after the FIRST part (the shell), so every later
171	 * part builds around the finished roof instead of the roof tool clearing the attic, gables and lofts after them. No
172	 * file yet (the roof part writes it, maybe in another copy at the same time): skipped with a note, never an error.
173	 * A part given { carve: true } (the stair joiner) may cut through earlier parts' floors and ceilings for its
174	 * stairwells: cells with air straight above or below. Walls stay refused.
175	 *   runParts(g, [["shell", shell.build], ["stairs", stairs.build, { carve: true }], ["garden", garden.build]],
176	 *     { palette: "palette.json", roof: "roof.json" })
177	 */
178	export function runParts(g, list, { palette, roof, log = console.log, report = "parts-report.json" } = {}) {
179	  // `mcd variant` rebuilds a finished build from its code with a roof change ($MCD_ROOF: JSON laid over roof.json)
180	  // and leaves the build's own reports alone ($MCD_PARTS_REPORT=none)
181	  if (process.env.MCD_PARTS_REPORT === "none") report = null;
182	  if (roof && process.env.MCD_ROOF) {
183	    const base = typeof roof === "string" ? (existsSync(roof) ? JSON.parse(readFileSync(roof, "utf8")) : null) : roof;
184	    if (base) roof = { ...base, ...JSON.parse(process.env.MCD_ROOF) };
185	  }
186	  const pal = typeof palette === "string" ? (existsSync(palette) ? JSON.parse(readFileSync(palette, "utf8")) : null) : palette;
187	  const allowed = pal ? new Set([...Object.values(pal.roles ?? {}).flat(), ...(pal.objects ?? [])].map(ns)) : null;
188	  const owned = new Set(), reports = [], cellsByPart = {};
189	  for (const [name, build, opts] of list) {
190	    const mine = new Set(), refused = [], off = new Map(), carved = [];
191	    const airy = (target, x, y, z) => !target.inBounds(x, y, z) || /(^|:)(cave_)?air$/.test(target.blockAt(x, y, z));
192	    const write = (target, x, y, z, block, state, nbt) => {
193	      const k = `${x},${y},${z}`;
194	      // a carving part (the stair joiner) may cut through an earlier part's floors and ceilings: a cell with air
195	      // straight above or below it. Walls (solid above and below) stay refused.
196	      if (owned.has(k) && opts?.carve && (airy(target, x, y + 1, z) || airy(target, x, y - 1, z))) { owned.delete(k); carved.push([x, y, z]); }
197	      if (owned.has(k)) { refused.push([x, y, z, ns(block).replace("minecraft:", ""), target.blockAt(x, y, z).replace("minecraft:", "")]); return; }
198	      const b = ns(block);
199	      if (allowed && b !== "minecraft:air" && b !== "minecraft:cave_air" && !allowed.has(b)) off.set(b, (off.get(b) ?? 0) + 1);
200	      target.set(x, y, z, block, state, nbt);
201	      mine.add(k);
202	    };
203	    const view = new Proxy(g, {
204	      get(target, prop) {
205	        if (prop === "set") return (x, y, z, block, state, nbt) => { write(target, x, y, z, block, state, nbt); return view; };
206	        if (prop === "unset") return (x, y, z) => { write(target, x, y, z, "minecraft:air"); return view; };
207	        if (prop === "fill") return (a, b, block, state) => {
208	          for (let x = Math.min(a[0], b[0]); x <= Math.max(a[0], b[0]); x++)
209	            for (let y = Math.min(a[1], b[1]); y <= Math.max(a[1], b[1]); y++)
210	              for (let z = Math.min(a[2], b[2]); z <= Math.max(a[2], b[2]); z++) write(target, x, y, z, block, state);
211	          return view;
212	        };
213	        const v = Reflect.get(target, prop);
214	        return typeof v === "function" ? v.bind(target) : v;
215	      },
216	    });
217	    // in a variant (a roof change) a part written for the old roof may throw: keep what it placed, say so, go on
218	    if (process.env.MCD_ROOF) { try { build(view); } catch (e) { log(`part ${name}: FAILED with this roof (${String(e.message).split("\n")[0]}); kept what it placed`); } }
219	    else build(view);
220	    for (const k of mine) owned.add(k);
221	    if (process.env.MCD_PARTS_CELLS) cellsByPart[name] = [...mine].map((k) => { const c = g.get(...k.split(",").map(Number)); return [k, c ? c.block.replace("minecraft:", "") + (c.state ? JSON.stringify(c.state) : "") : "air"]; });
222	    const r = { part: name, placed: mine.size, refused: refused.length, refusedAt: refused.slice(0, 8), ...(carved.length ? { carved: carved.length } : {}),
223	      offPalette: [...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n}`) };
224	    reports.push(r);
225	    log(`part ${name}: ${r.placed} placed` + (carved.length ? ` (${carved.length} cut through earlier floors)` : "") +
226	      (r.refused ? `; REFUSED ${r.refused} writes into earlier parts (x,y,z wanted had: ${r.refusedAt.map((p) => `${p[0]},${p[1]},${p[2]} ${p[3]} ${p[4]}`).join("; ")})` : "") +
227	      (r.offPalette.length ? `; OFF-PALETTE: ${r.offPalette.join(", ")}` : ""));
228	    if (roof && reports.length === 1) r.offPalette.push(...layRoof(g, roof, owned, log, allowed));   // the shell's to fix
229	  }
230	  if (report) writeFileSync(report, JSON.stringify(reports, null, 1));
231	  // $MCD_PARTS_CELLS=<file>: every part's cells, for measuring how much code each block cost (lab token audits)
232	  if (process.env.MCD_PARTS_CELLS) writeFileSync(process.env.MCD_PARTS_CELLS, JSON.stringify(cellsByPart));
233	  return reports;
234	}
235	
236	// The roof from its spec on top of the shell, inside runParts: the cells it lays are locked like a part's; the shell
237	// cells it clears (above the eave) are freed for the parts that come after.
238	function layRoof(g, roof, owned, log, allowed) {
239	  const spec = typeof roof === "string" ? (existsSync(roof) ? JSON.parse(readFileSync(roof, "utf8")) : null) : roof;
240	  if (!spec) { log(`roof: skipped, no ${roof} yet (the roof part writes it); every later part builds without it`); return []; }
241	  const before = new Map([...g].map((c) => [c.pos.join(","), c.block + JSON.stringify(c.state ?? {})]));
242	  const r = reroof(g, { ...spec, keep: spec.keep ?? [] });
243	  if (r.shift?.some(Boolean)) throw new Error(`roof: the overhang grew the site and moved every block by ${r.shift}; make the site larger so the roof fits`);
244	  let laid = 0, freed = 0;
245	  const off = new Map();
246	  for (const c of g) {
247	    const k = c.pos.join(",");
248	    if (before.get(k) !== c.block + JSON.stringify(c.state ?? {})) {
249	      owned.add(k); laid++;
250	      if (allowed && !allowed.has(ns(c.block))) off.set(ns(c.block), (off.get(ns(c.block)) ?? 0) + 1);
251	    }
252	    before.delete(k);
253	  }
254	  for (const k of before.keys()) if (owned.delete(k)) freed++;                 // cleared by the roof: open for later parts
255	  log(`roof: ${laid} placed (${spec.preset ?? spec.style ?? "roof"}), ${freed} shell cells above the eave cleared${r.refused ? `, ${r.refused} kept` : ""}` +
256	    (off.size ? `; OFF-PALETTE: ${[...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n}`).join(", ")} (fix roof.json)` : ""));
257	  return [...off].map(([b, n]) => `${b.replace("minecraft:", "")} x${n} (roof.json)`);
258	}
259	
260	// ---- shape brushes (curved forms; massing) — the model picks parameters, code draws the form ---------------------
261	export * from "./shapes-curved.mjs";
262	export * from "./shapes-massing.mjs";
263	
264	// ---- landscaping brushes (terrain, strata, boulders, water, trees, paths, bridges) — see references/landscaping.md --
265	export * from "./terrain.mjs";
266	
267	// ---- roofs by style name (gable, hip, pyramid, mansard, gambrel, flat-parapet, shed, dutch-gable) — references/roofs.md
268	export * from "./roofs.mjs";
269	
270	// ---- facade brushes (signage, pilasters, surrounds, glazing, fixtures, planters) — references/detail-language.md -----
271	// Each is a function on a grid (writes only where it may: air for projections, plain wall for in-place trim; returns
272	// { cells, skipped, notes, info }) and a B.* twin that returns the plan as g.set argument lists, unchecked.
273	// at = a wall cell (bottom-left of the band / opening as seen from outside), face = the side it looks out of.
274	import { commitGrid, lookGrid, tuples } from "./brush-core.mjs";
275	import { plaquePlan, signboardPlan, buntingPlan } from "./brush-sign.mjs";
276	import { clockPlan } from "./brush-clock.mjs";
277	import { pilasterPlan } from "./brush-pilaster.mjs";
278	import { surroundPlan, glazingPlan } from "./brush-surround.mjs";
279	import { fixturePlan, planterPlan } from "./brush-fixture.mjs";
280	const withLook = (g, o) => ({ ...o, look: lookGrid(g), dataVersion: o?.dataVersion ?? g.dataVersion });
281	/** Lettering in a band: plaque(g, "LEAGUE HALL", { at, face, width, height, letter?, material?, frame?, style?, relief? }) */
282	export const plaque = (g, text, o) => commitGrid(g, plaquePlan(text, withLook(g, o)), o);
283	/** A clock face on a tower: clock(g, { center, face, radius?: 2-4, dial?, bezel?, hands?, time?: "10:10", out?: 0|1 }) */
284	export const clock = (g, o) => commitGrid(g, clockPlan(withLook(g, o)), o);
285	/** A shop sign: signboard(g, "BAKERY", { at, face, mode: "wall"|"hanging", width?, height?, wood? }) */
286	export const signboard = (g, text, o) => commitGrid(g, signboardPlan(text, withLook(g, o)), o);
287	/** Banners along a row: bunting(g, { from, to, face, colors?, every?, pattern? }) */
288	export const bunting = (g, o) => commitGrid(g, buntingPlan(withLook(g, o)), o);
289	/** A profiled pilaster: pilaster(g, { at, face, height, width?, out?, material?, profile?, shoulder? }) */
290	export const pilaster = (g, o) => commitGrid(g, pilasterPlan(o), o);
291	/** An opening surround: surround(g, { at, face, width, height, preset?, trim?, keystone?, reveal?, door?, arch? }) */
292	export const surround = (g, o) => commitGrid(g, surroundPlan(withLook(g, o)), o);
293	/** Glazing: glazing(g, { at, face, width, height, preset: grid|shopfront|transom|sidelights, frame?, door? }) */
294	export const glazing = (g, o) => commitGrid(g, glazingPlan(withLook(g, o)), o);
295	/** A light fitting: fixture(g, { at, face, mount: bracket|arm|top|hang, lamp? }) */
296	export const fixture = (g, o) => commitGrid(g, fixturePlan(withLook(g, o)), o);
297	/** A planter: planter(g, { at, face, width, kind: box|ground, depth?, plants? }) */
298	export const planter = (g, o) => commitGrid(g, planterPlan(withLook(g, o)), o);
299	Object.assign(B, {
300	  plaque: (text, o) => tuples(plaquePlan(text, o)), clock: (o) => tuples(clockPlan(o)), signboard: (text, o) => tuples(signboardPlan(text, o)), bunting: (o) => tuples(buntingPlan(o)),
301	  pilaster: (o) => tuples(pilasterPlan(o)), surround: (o) => tuples(surroundPlan(o)), glazing: (o) => tuples(glazingPlan(o)),
302	  fixture: (o) => tuples(fixturePlan(o)), planter: (o) => tuples(planterPlan(o)),
303	});
304	/** Run detail-language rules from code (weather / vary presets, treatments on every opening): returns { grid, report }. */
305	export { applyDetail as paint } from "./detail-lang.mjs";
306

